<script setup>
import { computed, onMounted, ref } from 'vue';
import { useRouter } from 'vue-router';
import { cartApi } from '../../services/customerApi';
import { demoCart } from '../../mock/customerDemo';
import { useRoute } from 'vue-router';

const router = useRouter(); const route = useRoute(); const cart = ref({ items: [], totals: {} }); const error = ref(''); const loading = ref(true);
const money = (value) => new Intl.NumberFormat('vi-VN', { style: 'currency', currency: 'VND', maximumFractionDigits: 0 }).format(value || 0);
async function load() { if (route.query.demo === '1') { cart.value = structuredClone(demoCart); loading.value = false; return; } try { cart.value = (await cartApi.get()).data; } catch (e) { error.value = e.response?.data?.error?.message || 'Không thể tải giỏ thuê.'; } finally { loading.value = false; } }
async function remove(id) { if (route.query.demo === '1') { cart.value.items = cart.value.items.filter((item) => item.id !== id); return; } await cartApi.remove(id); await load(); }
function recalculate() {
  cart.value.totals = cart.value.items.reduce((result, item) => {
    const start = new Date(item.startDate); const end = new Date(item.endDate);
    const days = Math.max(1, Math.round((end - start) / 86400000) + 1);
    item.totals.rentalDays = days;
    item.totals.rentalAmount = (item.product.pricePerDay * days + 30000 * (item.selectedAccessories?.length || 0) * days) * item.quantity;
    item.totals.depositAmount = (item.product.depositAmount + 100000 * (item.selectedAccessories?.length || 0)) * item.quantity;
    result.rentalTotal += item.totals.rentalAmount; result.depositTotal += item.totals.depositAmount; return result;
  }, { rentalTotal: 0, depositTotal: 0, totalAmount: 0 });
  cart.value.totals.totalAmount = cart.value.totals.rentalTotal + cart.value.totals.depositTotal;
}
async function changeItem(item, field, value) {
  if (route.query.demo === '1') { item[field] = value; recalculate(); return; }
  await cartApi.update(item.id, { [field]: value }); await load();
}
const itemCount = computed(() => cart.value.items.length);
onMounted(load);
</script>
<template><div class="cart-page py-4"><div class="container"><div class="mb-4"><span class="eyebrow">GIỎ THUÊ</span><h1 class="display-6 fw-bold mb-1">Trang phục bạn đã chọn</h1><p class="text-muted mb-0">{{ itemCount }} sản phẩm · chỉnh ngày thuê trước khi gửi yêu cầu</p></div><div v-if="loading" class="py-5 text-center">Đang tải giỏ thuê...</div><div v-else-if="error" class="alert alert-warning">{{ error }}</div><div v-else class="row g-4"><section class="col-lg-8"><div v-if="!cart.items.length" class="empty-cart text-center"><i class="bi bi-bag-x fs-1"></i><h2 class="h5 mt-3">Giỏ thuê đang trống</h2><router-link to="/customer/demo" class="btn btn-primary mt-2">Khám phá màn demo</router-link></div><article v-for="item in cart.items" :key="item.id" class="cart-item mb-3"><div class="cart-image bg-light"><img v-if="item.product.images?.[0]?.url" :src="item.product.images[0].url"><i v-else class="bi bi-person-bounding-box fs-2 text-muted"></i></div><div class="flex-grow-1"><div class="d-flex justify-content-between gap-2"><div><span class="small text-muted">{{ item.product.shop?.name || 'Clarity shop' }}</span><h2 class="h5 mb-1">{{ item.product.name }}</h2><span class="badge rounded-pill text-bg-light border">Cọc hoàn lại {{ money(item.totals.depositAmount) }}</span></div><button class="btn btn-sm btn-link text-danger" aria-label="Xóa sản phẩm" @click="remove(item.id)"><i class="bi bi-trash3"></i></button></div><div class="row g-2 mt-2"><label class="col-sm-6 small">Ngày nhận<input :value="item.startDate.slice(0, 10)" type="date" class="form-control mt-1" @change="changeItem(item, 'startDate', $event.target.value)"></label><label class="col-sm-6 small">Ngày trả<input :value="item.endDate.slice(0, 10)" type="date" class="form-control mt-1" @change="changeItem(item, 'endDate', $event.target.value)"></label></div><div class="d-flex flex-wrap align-items-center justify-content-between gap-3 mt-3"><div class="quantity"><button @click="item.quantity > 1 && changeItem(item, 'quantity', item.quantity - 1)">−</button><strong>{{ item.quantity }}</strong><button @click="changeItem(item, 'quantity', item.quantity + 1)">+</button></div><div class="text-end"><span class="small text-muted d-block">{{ item.totals.rentalDays }} ngày thuê</span><strong class="text-danger">{{ money(item.totals.rentalAmount) }}</strong></div></div></div></article></section><aside class="col-lg-4"><div class="order-summary sticky-lg-top"><div class="d-flex justify-content-between align-items-center"><h2 class="h5 mb-0">Tóm tắt đơn thuê</h2><i class="bi bi-receipt"></i></div><div class="summary-row mt-4"><span>Tiền thuê</span><span>{{ money(cart.totals.rentalTotal) }}</span></div><div class="summary-row"><span>Tiền cọc hoàn lại</span><span>{{ money(cart.totals.depositTotal) }}</span></div><div class="summary-row"><span>Phí giao hàng</span><span>Tính ở bước sau</span></div><hr><div class="d-flex justify-content-between fs-5 fw-bold"><span>Tổng tạm tính</span><span>{{ money(cart.totals.totalAmount) }}</span></div><button :disabled="!cart.items.length" class="btn btn-primary w-100 py-3 mt-4" @click="router.push(route.query.demo === '1' ? '/customer/rental-request?demo=1' : '/customer/rental-request')">Tiếp tục đặt thuê <i class="bi bi-arrow-right ms-1"></i></button><p class="small text-muted text-center mt-3 mb-0"><i class="bi bi-shield-check"></i> Tiền cọc được sàn Clarity giữ an toàn</p></div></aside></div></div></div></template>
<style scoped>.cart-page{background:#faf8f5;min-height:72vh}.eyebrow{color:var(--bs-accent);font-size:.75rem;font-weight:800;letter-spacing:.12em}.cart-item,.order-summary,.empty-cart{background:#fff;border:1px solid #e9e1d9;border-radius:16px;padding:1.25rem}.cart-item{display:flex;gap:1.25rem}.cart-image{width:132px;height:160px;display:grid;place-items:center;flex:0 0 auto;border-radius:12px;overflow:hidden}.cart-image img{width:100%;height:100%;object-fit:cover}.quantity{display:inline-flex;align-items:center;border:1px solid #ded5cc;border-radius:8px;overflow:hidden}.quantity button{border:0;background:#f8f5f1;width:32px;height:32px;font-size:1.15rem}.quantity strong{min-width:36px;text-align:center}.summary-row{display:flex;justify-content:space-between;margin:.9rem 0;color:#655d57;font-size:.92rem}@media(max-width:575px){.cart-item{align-items:flex-start;padding:1rem}.cart-image{width:82px;height:105px}.cart-item h2{font-size:1rem}}</style>
